<script>
const batches=@json($batches);const packings=@json($packings);let nextId=0;const cart=document.getElementById('cart');
function optionsFor(batchId,sel){sel.replaceChildren(new Option('Choose pack',''));const b=batches.find(x=>String(x.id)===String(batchId));if(!b)return;packings.filter(x=>x.medicine_id===b.medicine_id).forEach(x=>sel.add(new Option(`${x.label} · ${x.units_per_pack} base units`,x.id)));}
function calculate(){let subtotal=0,tax=0;for(const row of cart.querySelectorAll('.pos-row')){const b=batches.find(x=>String(x.id)===row.querySelector('.batch').value),p=packings.find(x=>String(x.id)===row.querySelector('.packing').value),qty=Number(row.querySelector('.qty').value)||0;if(b&&p&&p.medicine_id===b.medicine_id){const gross=Math.round(Number(b.sale_price_per_unit)*100)*p.units_per_pack*qty;subtotal+=gross;tax+=gross-(Math.round(gross/(1+(Number(b.tax_rate)||0)/100)));}}const discount=Math.round((Number(document.getElementById('discount').value)||0)*100);document.getElementById('total').textContent=(Math.max(0,subtotal-discount)/100).toFixed(2);document.getElementById('tax').textContent='Calculated when posted';}
function addRow(batchId='',packingId=''){const i=nextId++;const row=document.createElement('div');row.className='pos-row';row.style.cssText='display:flex;flex-wrap:wrap;gap:10px;margin:12px 0;align-items:end';const b=document.createElement('select');b.className='batch';b.name=`items[${i}][batch_id]`;b.required=true;b.add(new Option('Select medicine / batch',''));batches.forEach(x=>b.add(new Option(`${x.name} | ${x.batch_no} | Exp ${x.expiry_date} | Stock ${x.quantity}`,x.id)));const p=document.createElement('select');p.className='packing';p.name=`items[${i}][packing_id]`;p.required=true;const q=document.createElement('input');q.className='qty';q.type='number';q.min='1';q.max='1000000';q.value=1;q.required=true;q.name=`items[${i}][quantity]`;const rm=document.createElement('button');rm.type='button';rm.textContent='Remove';rm.onclick=()=>{row.remove();calculate()};row.append(b,p,q,rm);cart.append(row);b.onchange=()=>{optionsFor(b.value,p);calculate()};p.onchange=calculate;q.oninput=calculate;if(batchId){b.value=String(batchId);optionsFor(b.value,p);if(packingId)p.value=String(packingId);}calculate();}
document.getElementById('addItem').onclick=()=>addRow();document.getElementById('discount').oninput=calculate;addRow();
document.getElementById('barcode').addEventListener('keydown',e=>{if(e.key!=='Enter')return;e.preventDefault();const barcode=e.currentTarget.value.trim();const packing=packings.find(p=>p.barcode===barcode);if(!packing){alert('Barcode not found');return;}const batch=batches.find(b=>b.medicine_id===packing.medicine_id);if(!batch){alert('No eligible stock for this barcode');return;}const empty=[...cart.querySelectorAll('.pos-row')].find(r=>!r.querySelector('.batch').value);if(empty){empty.querySelector('.batch').value=String(batch.id);const sel=empty.querySelector('.packing');optionsFor(batch.id,sel);sel.value=String(packing.id);}else{addRow(batch.id,packing.id);}e.currentTarget.value='';calculate();});
document.getElementById('posForm').addEventListener('submit',e=>{const rows=[...cart.querySelectorAll('.pos-row')];const ids=rows.map(r=>r.querySelector('.batch').value);if(!rows.length||ids.includes('')||new Set(ids).size!==ids.length){e.preventDefault();alert('Choose batches, avoid duplicates, and combine quantities.');return;}document.getElementById('postInvoice').disabled=true;});
</script>
